"""Identity + run defaults for robots generated by the Robot Foundry.

A Foundry robot is a normal simulator robot: its package is copied into a
sequence and the existing runner loads ``robot.xml``. To make it selectable
from the robot switcher, the generated MJCF carries a marker comment with the
Foundry project id. Detection therefore works from the stored model alone,
without importing the Foundry database into the execution path.

The catalog id is ``foundry:<foundry_id>`` so it can never collide with a
bundled robot id.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any

FOUNDRY_ROBOT_PREFIX = "foundry:"
FOUNDRY_MARKER_LABEL = "HeyWalk Foundry robot"

_ID_PATTERN = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,63}")
_MARKER_PATTERN = re.compile(
    rf"{re.escape(FOUNDRY_MARKER_LABEL)} id:\s*([A-Za-z0-9][A-Za-z0-9_-]{{0,63}})"
)

#: Foundry robots are joint-test robots. The reconstructed root is fixed so
#: the estimated actuator gains can hold test targets; there is no walking
#: policy for a generated morphology. Body poses are still streamed for the
#: live 3D view. Resets use the generated STAND keyframe (copied MicroDuck
#: contract); stiff estimated servos keep the validated implicitfast
#: integration, like ED-209.
FOUNDRY_SCENARIO_DEFAULTS: dict[str, Any] = {
    "fix_base": True,
    "locomotion": False,
    "include_body_poses": True,
    "keyframe": "STAND",
    "integrator": "implicitfast",
}


@dataclass(frozen=True)
class FoundryRobotRef:
    """A Foundry robot detected from an installed MJCF."""

    foundry_id: str
    name: str | None = None

    @property
    def id(self) -> str:
        return foundry_robot_id(self.foundry_id)

    @property
    def scenario_defaults(self) -> dict[str, Any]:
        return dict(FOUNDRY_SCENARIO_DEFAULTS)


def foundry_robot_id(foundry_id: str) -> str:
    return f"{FOUNDRY_ROBOT_PREFIX}{foundry_id}"


def foundry_id_from_robot_id(robot_id: str) -> str | None:
    """Return the Foundry id for a ``foundry:<id>`` catalog id, else None."""
    if not isinstance(robot_id, str) or not robot_id.startswith(FOUNDRY_ROBOT_PREFIX):
        return None
    value = robot_id[len(FOUNDRY_ROBOT_PREFIX) :].strip()
    if not _ID_PATTERN.fullmatch(value):
        return None
    return value


def is_foundry_robot_id(robot_id: str) -> bool:
    return foundry_id_from_robot_id(robot_id) is not None


def foundry_marker(foundry_id: str) -> str:
    if not _ID_PATTERN.fullmatch(foundry_id):
        raise ValueError(f"Invalid Foundry project id: {foundry_id!r}")
    return f"<!-- {FOUNDRY_MARKER_LABEL} id: {foundry_id} -->"


def stamp_foundry_marker(xml: str, foundry_id: str) -> str:
    """Add the detection marker to an MJCF, after the XML declaration."""
    if not isinstance(xml, str) or not xml.strip():
        return xml
    marker = foundry_marker(foundry_id)
    if FOUNDRY_MARKER_LABEL in xml[:4096]:
        return xml
    stripped = xml.lstrip()
    if stripped.startswith("<?xml"):
        end = xml.find("?>")
        if end >= 0:
            end += 2
            return f"{xml[:end]}\n{marker}\n{xml[end:]}"
    return f"{marker}\n{xml}"


def detect_foundry_robot(xml_text: str) -> FoundryRobotRef | None:
    """Return the Foundry robot named by an MJCF marker, if present."""
    if not isinstance(xml_text, str):
        return None
    match = _MARKER_PATTERN.search(xml_text[:4096])
    if match is None:
        return None
    return FoundryRobotRef(foundry_id=match.group(1))


__all__ = [
    "FOUNDRY_MARKER_LABEL",
    "FOUNDRY_ROBOT_PREFIX",
    "FOUNDRY_SCENARIO_DEFAULTS",
    "FoundryRobotRef",
    "detect_foundry_robot",
    "foundry_id_from_robot_id",
    "foundry_marker",
    "foundry_robot_id",
    "is_foundry_robot_id",
    "stamp_foundry_marker",
]
